function roundTrip(strs: string[]): string[] {
  const encode = (list: string[]): string =>
    list.map(s => s.split("~").join("~~").split(",").join("~,") + ",").join("");

  const decode = (data: string): string[] => {
    const out: string[] = [];
    let cur = "";
    for (let i = 0; i < data.length; i++) {
      const c = data[i];
      if (c === "~") cur += data[++i]; // escaped: take the next character literally
      else if (c === ",") { out.push(cur); cur = ""; }
      else cur += c;
    }
    return out;
  };

  return decode(encode(strs));
}

