class Solution:
    def encode(self, strs: List[str]) -> str:
        return "".join(s.replace("~", "~~").replace(",", "~,") + "," for s in strs)

    def decode(self, data: str) -> List[str]:
        out, cur, i = [], [], 0
        while i < len(data):
            c = data[i]
            if c == "~":
                i += 1
                cur.append(data[i])  # escaped: take the next character literally
            elif c == ",":
                out.append("".join(cur))
                cur = []
            else:
                cur.append(c)
            i += 1
        return out

    def roundTrip(self, strs: List[str]) -> List[str]:
        return self.decode(self.encode(strs))

