function roundTrip(strs: string[]): string[] {
  const encode = (list: string[]): string => list.map(s => s.length + "#" + s).join("");

  const decode = (data: string): string[] => {
    const out: string[] = [];
    let i = 0;
    while (i < data.length) {
      const hash = data.indexOf("#", i);
      const len = Number(data.slice(i, hash));
      out.push(data.slice(hash + 1, hash + 1 + len));
      i = hash + 1 + len;
    }
    return out;
  };

  return decode(encode(strs));
}

